import ChartKit from '@gravity-ui/chartkit';
import type {ChartKitRef, ChartKitProps} from '@gravity-ui/chartkit';
import {Alert, Card, Flex, Loader, SegmentedRadioGroup, Text} from '@gravity-ui/uikit';

import './chartkit-setup';
import {
